import {linkedSettingKeys,addSettingAttack,removeSettingAttack,clearSettingLinks} from './setting-link.js';
import {attachPlayerHover} from './player-hover.js';
import {setPlayerPosition,movePlayerRow} from './roster-edit.js';
import {definitions as D} from './definitions.js';
import {calculate,teamTotal,calculatedKeys} from './calculations.js';
import {repository,blankSet} from './repository.js';
import {rosterFor,gamePlayerTotals,completeGame} from './services.js';
import {positions,escapeHTML as esc} from './config.js';
const repo=repository(),params=new URLSearchParams(location.search);
let game=repo.getGame(params.get('game'));
if(!game){location.replace('index.html#games');throw Error('경기를 찾을 수 없습니다.')}
let state=game,active=0,selected=null,editing=false,history=[];
const count=game.maxSets,readonly=params.get('view')==='1'||game.status==='completed';
const displayPlayer=p=>({id:p.playerId,name:p.name,position:p.position,role:p.role,label:p.name});
let rosters;function syncRosters(){rosters=state.sets.map((_,i)=>rosterFor(state,i).map(displayPlayer));}syncRosters();
const blank=()=>({sets:rosters.map(rs=>blankSet(rs.map(p=>({playerId:p.id}))))});
document.querySelector('.match').textContent=`${game.team} vs ${game.opponent}`;
document.querySelector('#gameCaption').textContent=`${game.date} · ${game.competition}${game.location?' · '+game.location:''}`;
document.querySelector('#back').href=`index.html#game/${game.id}`;
document.querySelector('#finish').hidden=readonly;
document.querySelector('#undo').hidden=readonly;
document.querySelector('#reset').hidden=readonly;
if(readonly)document.querySelector('.legend').textContent='조회 모드 · 기록 수정은 경기 상세에서 선택하세요.';
const grid=document.querySelector('#grid'),tabs=document.querySelector('#tabs'),wrap=document.querySelector('#gridWrap');
function save(){if(readonly)return;if(state.status==='scheduled')state.status='in_progress';document.querySelector('#saved').textContent=repo.saveGame(state)?'서버 저장 중':repo.getError();}
function commit(change){if(readonly)return;history.push({active,data:structuredClone(state.sets[active])});if(history.length>300)history.shift();change();save();refresh();document.querySelector('#undo').disabled=false;}
function undo(){if(readonly)return;const h=history.pop();if(!h)return;state.sets[h.active]=h.data;if(active!==h.active){active=h.active;selected=null;render()}else refresh();save();document.querySelector('#undo').disabled=!history.length}
const percent=k=>['F','G','N','T','U','V','W','AH','AI','AJ'].includes(k);
function format(v,k){if(v===null||v===undefined||!Number.isFinite(v))return '−';return percent(k)?v.toFixed(1)+'%':Number.isInteger(v)?String(v):v.toFixed(1)}
function rows(){if(active<count)return rosters[active].map(p=>({p,raw:state.sets[active].players[p.id]||{},sets:1}));return gamePlayerTotals(state).map(x=>({p:displayPlayer(x.p),raw:x.raw,sets:Math.max(1,x.setCount)}));}
function render(){tabs.innerHTML=[...Array.from({length:count},(_,i)=>`${i+1}세트`),'종합'].map((x,i)=>`<button role="tab" aria-selected="${i===active}" data-set="${i}">${x}</button>`).join('');document.querySelector('#reset').disabled=readonly||active===count;
 let h='<colgroup><col style="width:150px">'+D.columns.map(c=>`<col style="width:${c.calculated?46:32}px">`).join('')+'</colgroup><thead><tr><th class="frozen" rowspan="3">선수 / 포지션</th>';D.groups.forEach((name,g)=>h+=`<th class="group g${g} group-start" colspan="${D.columns.filter(c=>c.group===g).length}">${name}${g===5?' <small>(세터는 토스)</small>':''}</th>`);h+='</tr><tr>';
 for(let i=0;i<D.columns.length;){const c=D.columns[i];let n=1;if(c.sub)while(D.columns[i+n]?.group===c.group&&D.columns[i+n]?.label===c.label)n++;h+=`<th class="g${c.group} group ${i===0||D.columns[i-1].group!==c.group?'group-start':''}" ${c.sub?`colspan="${n}"`:'rowspan="2"'}>${c.label}</th>`;i+=n}h+='</tr><tr>';for(const c of D.columns)if(c.sub)h+=`<th class="group g${c.group}">${c.sub}</th>`;h+='</tr></thead><tbody>';
 let previousRole=null;rows().forEach(({p},r)=>{if(p.role!==previousRole){h+=`<tr class="roster-divider ${p.role==='bench'?'bench-divider':''}"><th class="frozen">${p.role==='bench'?'대기 선수':'코트 엔트리'}</th><td colspan="47"></td></tr>`;previousRole=p.role;}h+=`<tr data-player-row="${p.id}" data-role="${p.role}"><th class="frozen"><div class="player-tools"><span class="player-name" title="${esc(p.name)}">${esc(p.name)}</span><select data-position="${p.id}" aria-label="${esc(p.name)} 포지션" ${readonly||active===count?'disabled':''}>${[...new Set([...positions,p.position])].filter(Boolean).map(pos=>`<option value="${esc(pos)}" ${pos===p.position?'selected':''}>${esc(pos)}</option>`).join('')}</select>${readonly||active===count?'':`<span class="row-moves"><button type="button" data-move-player="${p.id}" data-direction="-1" aria-label="${esc(p.name)} 위로 이동" ${!rows()[r-1]?'disabled':''}>↑</button><button type="button" data-move-player="${p.id}" data-direction="1" aria-label="${esc(p.name)} 아래로 이동" ${!rows()[r+1]?'disabled':''}>↓</button></span>`}</div></th>`;D.columns.forEach((c,i)=>h+=`<td data-row="${r}" data-col="${i}" data-key="${c.key}" class="${readonly||active===count||c.calculated?'calc':'editable'} ${i===0||D.columns[i-1].group!==c.group?'group-start':''}" tabindex="${r===0&&i===1?0:-1}" aria-label="${esc(p.label)} ${D.groups[c.group]} ${c.label} ${c.sub}"></td>`);h+='</tr>'});h+='</tbody><tfoot><tr><th class="frozen">팀 종합</th>'+D.columns.map(c=>`<td data-total="${c.key}" class="calc"></td>`).join('')+'</tr></tfoot>';grid.innerHTML=h;renderMemo();renderOpponent();renderScores();refresh();}
function refresh(){const rs=rows(),team=teamTotal(rs.map(x=>x.raw),active===count?(state.status==='completed'?state.result.played:count):1);rs.forEach(({raw,sets},r)=>{const values=calculate(raw,team,sets);for(const c of D.columns){const cell=grid.querySelector(`[data-row="${r}"][data-key="${c.key}"]`);if(!cell.querySelector('input'))cell.textContent=format(values[c.key],c.key)}});for(const c of D.columns)grid.querySelector(`[data-total="${c.key}"]`).textContent=format(team[c.key],c.key);refreshOpponent();refreshScores();}
function choose(cell){grid.querySelector('.selected')?.classList.remove('selected');if(!cell)return;selected=cell;cell.classList.add('selected');grid.querySelectorAll('[tabindex="0"]').forEach(x=>x.tabIndex=-1);cell.tabIndex=0;cell.focus({preventScroll:true});document.querySelector('#selection').textContent=cell.getAttribute('aria-label')+(cell.classList.contains('calc')?' · 자동 계산':' · 좌클릭 +1 / 우클릭 −1');}
function change(cell,delta){if(readonly||active===count||!cell.classList.contains('editable'))return;const p=rosters[active][+cell.dataset.row],k=cell.dataset.key;const old=state.sets[active].players[p.id][k]||0;const value=Math.max(0,old+delta);if(value===old)return;commit(()=>{if(delta<0&&linkedSettingKeys.includes(k))removeSettingAttack(state.sets[active],p.id,k);else state.sets[active].players[p.id][k]=value;});cell.classList.add('flash');setTimeout(()=>cell.classList.remove('flash'),90)}
grid.addEventListener('click',e=>{if(e.target.tagName==='INPUT'||editing)return;const c=e.target.closest('td[data-row]');if(!c)return;choose(c);if(!readonly&&active<count&&linkedSettingKeys.includes(c.dataset.key)){openAttackerPicker(c);return;}change(c,1)});
wrap.addEventListener('contextmenu',e=>{e.preventDefault();if(editing)return;const c=e.target.closest('td[data-row]');if(c){choose(c);change(c,-1)}});
function edit(cell){if(readonly||editing||active===count||!cell?.classList.contains('editable'))return;editing=true;const p=rosters[active][+cell.dataset.row],key=cell.dataset.key,input=document.createElement('input');input.type='number';input.min='0';input.step='1';input.value=state.sets[active].players[p.id][key]||0;input.setAttribute('aria-label','기록 숫자 수정');cell.textContent='';cell.append(input);input.focus();input.select();let done=false;const finish=apply=>{if(done)return;const value=Number(input.value);if(apply&&(!/^\d+$/.test(input.value)||!Number.isSafeInteger(value)||value<0)){input.setCustomValidity('0 이상의 정수를 입력하세요.');input.reportValidity();return}done=true;editing=false;input.remove();if(apply&&value!==(state.sets[active].players[p.id][key]||0))commit(()=>{state.sets[active].players[p.id][key]=value;if(linkedSettingKeys.includes(key))clearSettingLinks(state.sets[active],p.id,key);});else refresh();choose(cell)};input.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();finish(true)}if(e.key==='Escape'){e.preventDefault();finish(false)}if(e.key==='Tab'){e.preventDefault();finish(true)}});input.addEventListener('blur',()=>finish(false))}
grid.addEventListener('keydown',e=>{if(editing)return;const c=e.target.closest('td[data-row]');if(!c)return;if(e.key==='Enter'){e.preventDefault();edit(c);return}let r=+c.dataset.row,i=+c.dataset.col;if(e.key==='Tab'){e.preventDefault();let cells=[...grid.querySelectorAll('tbody td.editable')];if(!cells.length)return;const pos=cells.indexOf(c);choose(cells[(pos+(e.shiftKey?-1:1)+cells.length)%cells.length]);selected.scrollIntoView({block:'nearest',inline:'nearest'});return}if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowUp')r--;if(e.key==='ArrowDown')r++;if(e.key==='ArrowLeft')i--;if(e.key==='ArrowRight')i++;const next=grid.querySelector(`[data-row="${r}"][data-col="${i}"]`);if(next){choose(next);next.scrollIntoView({block:'nearest',inline:'nearest'})}});
tabs.addEventListener('click',e=>{if(!e.target.dataset.set)return;active=+e.target.dataset.set;selected=null;render()});
document.querySelector('#undo').onclick=undo;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();undo()}});
function renderOpponent(){const labels=['서브실패','공격실패','수비범실','넷터치','오버넷','캐치볼','더블컨택'];document.querySelector('#opponent').innerHTML='<table><thead><tr>'+labels.map(l=>`<th>${l}</th>`).join('')+'<th>합계</th></tr></thead><tbody><tr>'+labels.map((l,i)=>`<td class="${!readonly&&active<count?'editable':'calc'}" data-opp="${i}" tabindex="0" aria-label="상대범실 ${l}"></td>`).join('')+'<td id="oppTotal" class="calc"></td></tr></tbody></table>';}
function refreshOpponent(){const values=active<count?state.sets[active].opponent:Array.from({length:7},(_,i)=>state.sets.reduce((n,s)=>n+s.opponent[i],0));document.querySelectorAll('[data-opp]').forEach(c=>c.textContent=values[+c.dataset.opp]);document.querySelector('#oppTotal').textContent=values.reduce((a,b)=>a+b,0);}
const opp=document.querySelector('#opponent');function oppChange(e,delta){const c=e.target.closest('[data-opp]');if(readonly||!c||active===count)return;const i=+c.dataset.opp,old=state.sets[active].opponent[i],v=Math.max(0,old+delta);if(old!==v)commit(()=>state.sets[active].opponent[i]=v)}opp.addEventListener('click',e=>oppChange(e,1));opp.addEventListener('contextmenu',e=>{e.preventDefault();oppChange(e,-1)});opp.addEventListener('change',e=>{const i=e.target;if(readonly||i.dataset.score===undefined)return;const value=Number(i.value);if(/^\d+$/.test(i.value)&&Number.isSafeInteger(value))commit(()=>state.sets[active].score[+i.dataset.score]=value);else refreshOpponent()});
document.querySelector('#help').onclick=()=>document.querySelector('#helpDialog').showModal();document.querySelector('#notes').replaceChildren(...D.notes.map(n=>{const p=document.createElement('p');p.textContent=n;return p}));document.querySelector('#reset').onclick=()=>document.querySelector('#resetDialog').showModal();document.querySelector('#cancelReset').onclick=()=>document.querySelector('#resetDialog').close();document.querySelector('#confirmReset').onclick=()=>{if(active<count)commit(()=>state.sets[active]=blank().sets[active]);document.querySelector('#resetDialog').close()};
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_volleyball_records',description:'현재 배구 기록표와 세트별 기록을 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input={})=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('입력 인자가 없는 조회 도구입니다.');return {activeSet:active+1,records:structuredClone(state),readonly}}})).catch(()=>{})}catch{}}

function renderScores(){document.querySelector('#setScore').innerHTML=active<count?`<span>${active+1}세트</span><label>${esc(game.team)} <input data-topscore="0" type="number" min="0" step="1" ${readonly?'disabled':''}></label><span>:</span><label>${esc(game.opponent)} <input data-topscore="1" type="number" min="0" step="1" ${readonly?'disabled':''}></label>`:'<span>전체 세트 종합 · 포지션/순서는 경기 생성 기준</span>';}
function refreshScores(){document.querySelectorAll('[data-topscore]').forEach(i=>i.value=state.sets[active].score[+i.dataset.topscore]);}
document.querySelector('#setScore').addEventListener('change',e=>{if(readonly)return;const i=e.target;if(i.dataset.topscore===undefined)return;const v=Number(i.value);if(/^\d+$/.test(i.value)&&Number.isSafeInteger(v))commit(()=>state.sets[active].score[+i.dataset.topscore]=v);else refreshScores()});
document.querySelector('#finish').onclick=()=>{document.querySelector('#finishError').textContent='';document.querySelector('#finishDialog').showModal()};
document.querySelector('#cancelFinish').onclick=()=>document.querySelector('#finishDialog').close();
document.querySelector('#confirmFinish').onclick=async()=>{try{const completed=completeGame(state);if(!repo.saveGame(completed))throw Error(repo.getError());await repo.flush?.();location.href=`index.html#game/${game.id}`}catch(e){document.querySelector('#finishError').textContent=e.message}};
if(repo.getError())document.querySelector('#saved').textContent=repo.getError();

// Roster presentation is separate from player-keyed raw records and court slots.
grid.addEventListener('change',e=>{const input=e.target.closest('[data-position]');if(!input||readonly||active===count||!positions.includes(input.value))return;setPlayerPosition(state,active,input.dataset.position,input.value);syncRosters();save();});
grid.addEventListener('click',e=>{const button=e.target.closest('[data-move-player]');if(!button||readonly||active===count||editing)return;if(!movePlayerRow(state,active,button.dataset.movePlayer,Number(button.dataset.direction)))return;syncRosters();selected=null;save();render();grid.querySelector(`[data-move-player="${button.dataset.movePlayer}"][data-direction="${button.dataset.direction}"]`)?.focus({preventScroll:true});});
function renderMemo(){const area=document.querySelector('#setMemo');area.readOnly=readonly||active===count;area.value=active<count?(state.setNotes?.[active]||''):(state.setNotes||[]).map((note,i)=>note?`${i+1}세트: ${note}`:'').filter(Boolean).join('\n');area.placeholder=active<count?'경기 중 확인할 내용을 적으세요.':'세트별 메모가 여기에 표시됩니다.';}
document.querySelector('#setMemo').addEventListener('input',e=>{if(readonly||active===count)return;state.setNotes??=Array(count).fill('');state.setNotes[active]=e.target.value;save();});

attachPlayerHover(grid,wrap);

const attackerDialog=document.createElement('div');attackerDialog.className='attacker-popover';attackerDialog.hidden=true;attackerDialog.setAttribute('role','dialog');attackerDialog.setAttribute('aria-labelledby','attackerTitle');attackerDialog.innerHTML='<div class="attacker-heading"><strong id="attackerTitle"></strong><button type="button" id="cancelAttacker" aria-label="공격수 목록 닫기">×</button></div><div id="attackerOptions" class="attacker-options"></div><small class="attacker-hint">선택 시 연결 기록 · 공격 시도 +1</small>';document.body.append(attackerDialog);let pendingSetting=null;
function closeAttackerPicker(){attackerDialog.hidden=true;pendingSetting=null;}
function positionAttackerPicker(cell){const rect=cell.getBoundingClientRect(),width=attackerDialog.offsetWidth,height=attackerDialog.offsetHeight;let left=rect.right+6;if(left+width>window.innerWidth-8)left=rect.left-width-6;attackerDialog.style.left=Math.max(8,Math.min(left,window.innerWidth-width-8))+'px';attackerDialog.style.top=Math.max(8,Math.min(rect.top,window.innerHeight-height-8))+'px';}
function openAttackerPicker(cell){const player=rosters[active][Number(cell.dataset.row)],column=D.columns.find(c=>c.key===cell.dataset.key);pendingSetting={set:active,setterId:player.id,key:column.key,cell};document.querySelector('#attackerTitle').textContent=`${player.name} · ${column.sub}`;document.querySelector('#attackerOptions').innerHTML=rosters[active].filter(p=>p.id!==player.id).map(p=>`<button type="button" data-attacker="${p.id}"><b>${esc(p.name)}</b><span class="attacker-position">${esc(p.position)}</span></button>`).join('');attackerDialog.hidden=false;positionAttackerPicker(cell);document.querySelector('#playerHover')?.setAttribute('hidden','');}
document.querySelector('#cancelAttacker').onclick=closeAttackerPicker;attackerDialog.addEventListener('click',e=>{const button=e.target.closest('[data-attacker]');if(!button||!pendingSetting||readonly)return;const pending=pendingSetting;closeAttackerPicker();if(pending.set!==active)return;commit(()=>addSettingAttack(state.sets[active],pending.setterId,pending.key,button.dataset.attacker));choose(pending.cell);highlightLinkedAttacker(button.dataset.attacker);});
document.addEventListener('pointerdown',e=>{if(!attackerDialog.hidden&&!attackerDialog.contains(e.target))closeAttackerPicker();});document.addEventListener('keydown',e=>{if(attackerDialog.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();const cell=pendingSetting?.cell;closeAttackerPicker();cell?.focus({preventScroll:true});}else if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();e.stopPropagation();const buttons=[...attackerDialog.querySelectorAll('[data-attacker]')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}},true);
wrap.addEventListener('scroll',closeAttackerPicker,{passive:true});window.addEventListener('resize',closeAttackerPicker);window.addEventListener('blur',closeAttackerPicker);new MutationObserver(closeAttackerPicker).observe(grid,{childList:true});

let linkedHighlightTimer;
function highlightLinkedAttacker(playerId){clearTimeout(linkedHighlightTimer);grid.querySelectorAll('.linked-attacker-row').forEach(row=>row.classList.remove('linked-attacker-row'));const row=[...grid.querySelectorAll('[data-player-row]')].find(row=>row.dataset.playerRow===playerId);if(!row)return;row.classList.add('linked-attacker-row');linkedHighlightTimer=setTimeout(()=>row.classList.remove('linked-attacker-row'),2500);}
